/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to an Excel file. LoadWWPContext.Call(&WWPContext)
Do 'OpenDocument'
&CellRow = 1 &FirstColumn = 1
Do 'LoadGridState'
Do 'WriteFilters'
Do 'WriteColumnTitles'
Do 'WriteData'
Do 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'OpenDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Random = Random() * 10000 &Filename = !"trnsprogramasWWExport-" + &Random.ToString().Trim() + !".xlsx"
&ExcelDocument.Open(&Filename) Do 'CheckStatus' &ExcelDocument.Clear()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If not (&TFprogCodigo.IsEmpty() AND &TFprogCodigo_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Codigo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFprogCodigo WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFprogCodigo_To EndIf If not (&TFprogDescricao_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Descricao") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFprogDescricao_Sel) Else If not (&TFprogDescricao.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Descricao") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFprogDescricao) EndIf EndIf If not (&TFprogSigla_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Sigla") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFprogSigla_Sel) Else If not (&TFprogSigla.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Sigla") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFprogSigla) EndIf EndIf If not (&TFprogApareceRemessa_Sels.Count = 0) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Aparece na Remessa") &i = 1 For &TFprogApareceRemessa_Sel in &TFprogApareceRemessa_Sels If &i = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' Else &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += ', ' EndIf do Case Case &TFprogApareceRemessa_Sel.ToString().Trim() = "S" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Sim"
Case &TFprogApareceRemessa_Sel.ToString().Trim() = "N" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Não"
EndCase &i += 1 EndFor EndIf If not (&TFprogOrigem_Sels.Count = 0) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Origem") &i = 1 For &TFprogOrigem_Sel in &TFprogOrigem_Sels If &i = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' Else &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += ', ' EndIf do Case Case &TFprogOrigem_Sel.ToString().Trim() = "U" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Federeal"
Case &TFprogOrigem_Sel.ToString().Trim() = "E" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Estadual"
Case &TFprogOrigem_Sel.ToString().Trim() = "M" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Municipal"
EndCase &i += 1 EndFor EndIf If not (&TFproTipoLicitacao_Sels.Count = 0) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Tipo Licitacao") &i = 1 For &TFproTipoLicitacao_Sel in &TFproTipoLicitacao_Sels If &i = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' Else &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += ', ' EndIf do Case Case &TFproTipoLicitacao_Sel.ToString().Trim() = "G" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Geral"
Case &TFproTipoLicitacao_Sel.ToString().Trim() = "E" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Específica"
EndCase &i += 1 EndFor EndIf If not (&TFprogStatus_Sels.Count = 0) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Situacao") &i = 1 For &TFprogStatus_Sel in &TFprogStatus_Sels If &i = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' Else &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += ', ' EndIf do Case Case &TFprogStatus_Sel.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Ativo"
Case &TFprogStatus_Sel.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Intivo"
EndCase &i += 1 EndFor EndIf &CellRow += 2
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&VisibleColumnCount = 0 If &Session.Get(!'trnsprogramasWWColumnsSelector') <> '' &ColumnsSelectorXML = &Session.Get(!'trnsprogramasWWColumnsSelector') &ColumnsSelector.FromXml(&ColumnsSelectorXML) Else Do 'InitializeColumnsSelector' EndIf
&ColumnsSelector.Columns.Sort(!'Order') For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = GetMessageText(iif(&ColumnsSelector_Column.DisplayName.IsEmpty(), &ColumnsSelector_Column.ColumnName, &ColumnsSelector_Column.DisplayName)) &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Color = 11 &VisibleColumnCount += 1 EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsprogramas order progDescricao when &OrderedBy = 1 AND &OrderedDsc = False order (progDescricao) when &OrderedBy = 1 AND &OrderedDsc = True order progCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (progCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order progSigla when &OrderedBy = 3 AND &OrderedDsc = False order (progSigla) when &OrderedBy = 3 AND &OrderedDsc = True order progApareceRemessa when &OrderedBy = 4 AND &OrderedDsc = False order (progApareceRemessa) when &OrderedBy = 4 AND &OrderedDsc = True order progOrigem when &OrderedBy = 5 AND &OrderedDsc = False order (progOrigem) when &OrderedBy = 5 AND &OrderedDsc = True order proTipoLicitacao when &OrderedBy = 6 AND &OrderedDsc = False order (proTipoLicitacao) when &OrderedBy = 6 AND &OrderedDsc = True order progStatus when &OrderedBy = 7 AND &OrderedDsc = False order (progStatus) when &OrderedBy = 7 AND &OrderedDsc = True
using trnsprogramasWWDS(&TFprogCodigo, &TFprogCodigo_To, &TFprogDescricao, &TFprogDescricao_Sel, &TFprogSigla, &TFprogSigla_Sel , &TFprogApareceRemessa_Sels, &TFprogOrigem_Sels, &TFproTipoLicitacao_Sels, &TFprogStatus_Sels)
// Write cell values &CellRow += 1
Do 'BeforeWriteLine' &VisibleColumnCount = 0 For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True Do Case Case &ColumnsSelector_Column.ColumnName = !'progCodigo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = progCodigo Case &ColumnsSelector_Column.ColumnName = !'progDescricao' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(progDescricao) Case &ColumnsSelector_Column.ColumnName = !'progSigla' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(progSigla) Case &ColumnsSelector_Column.ColumnName = !'progApareceRemessa' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = '' do Case Case progApareceRemessa.ToString().Trim() = "S" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Sim"
Case progApareceRemessa.ToString().Trim() = "N" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Não"
EndCase Case &ColumnsSelector_Column.ColumnName = !'progOrigem' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = '' do Case Case progOrigem.ToString().Trim() = "U" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Federeal"
Case progOrigem.ToString().Trim() = "E" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Estadual"
Case progOrigem.ToString().Trim() = "M" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Municipal"
EndCase Case &ColumnsSelector_Column.ColumnName = !'proTipoLicitacao' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = '' do Case Case proTipoLicitacao.ToString().Trim() = "G" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Geral"
Case proTipoLicitacao.ToString().Trim() = "E" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Específica"
EndCase Case &ColumnsSelector_Column.ColumnName = !'progStatus' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = '' do Case Case progStatus.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Ativo"
Case progStatus.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Intivo"
EndCase EndCase &VisibleColumnCount += 1 EndIf EndFor
Do 'AfterWriteLine'
Endfor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ExcelDocument.Save() Do 'CheckStatus' &ExcelDocument.Close()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CheckStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If (&ExcelDocument.ErrCode <> 0) &Filename = "" &ErrorMessage = &ExcelDocument.ErrDescription &ExcelDocument.Close() Return EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'InitializeColumnsSelector'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ColumnsSelector = new WWPColumnsSelector() WWP_ColumnsSelector_Add(&ColumnsSelector, !"progCodigo", '', !'Codigo', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"progDescricao", '', !'Descricao', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"progSigla", '', !'Sigla', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"progApareceRemessa", '', !'Aparece na Remessa', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"progOrigem", '', !'Origem', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"proTipoLicitacao", '', !'Tipo Licitacao', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"progStatus", '', !'Situacao', True, '')
&UserCustomValue = LoadColumnsSelectorState.Udp(!'trnsprogramasWWColumnsSelector') If not(&UserCustomValue.IsEmpty()) &ColumnsSelectorAux.FromXml(&UserCustomValue) WWP_ColumnSelector_UpdateColumns(&ColumnsSelectorAux, &ColumnsSelector) EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsprogramasWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsprogramasWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsprogramasWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFPROGCODIGO" &TFprogCodigo.FromString(&GridStateFilterValue.Value) &TFprogCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPROGDESCRICAO" &TFprogDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPROGDESCRICAO_SEL" &TFprogDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPROGSIGLA" &TFprogSigla.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPROGSIGLA_SEL" &TFprogSigla_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPROGAPARECEREMESSA_SEL" &TFprogApareceRemessa_SelsJson = &GridStateFilterValue.Value &TFprogApareceRemessa_Sels.FromJson(&TFprogApareceRemessa_SelsJson) Case &GridStateFilterValue.Name = !"TFPROGORIGEM_SEL" &TFprogOrigem_SelsJson = &GridStateFilterValue.Value &TFprogOrigem_Sels.FromJson(&TFprogOrigem_SelsJson) Case &GridStateFilterValue.Name = !"TFPROTIPOLICITACAO_SEL" &TFproTipoLicitacao_SelsJson = &GridStateFilterValue.Value &TFproTipoLicitacao_Sels.FromJson(&TFproTipoLicitacao_SelsJson) Case &GridStateFilterValue.Name = !"TFPROGSTATUS_SEL" &TFprogStatus_SelsJson = &GridStateFilterValue.Value &TFprogStatus_Sels.FromJson(&TFprogStatus_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforeWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'AfterWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub

	/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */

parm(out:&Filename, out:&ErrorMessage);

	/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
